    /**
     * @description Serializer unificado para Order con lógica condicional.
     * CARACTERÍSTICAS:
     * - Un solo serializer para todas las operaciones
     * - Respuestas condicionales basadas en el contexto
     * - Compatibilidad con código existente
     * - Optimizado para performance
     */
    OrderRequest: {
      owner_id?: number;
      branch_id?: number;
      client_id?: number | null;
      processed_by_id?: number | null;
      delivered_by_id?: number | null;
      /** @description Table assigned to the order (optional) */
      table?: number | null;
      table_id?: number | null;
      /**
       * @description PENDING = orden activa/abierta; COMPLETED = finalizada
       *
       * * `DRAFT` - Draft
       * * `PENDING` - Pending
       * * `IN_PROGRESS` - In Progress
       * * `COMPLETED` - Completed
       * * `CANCELLED` - Cancelled
       * * `RETURNED` - Returned
       * * `REFUNDED` - Refunded
       * @enum {string}
       */
      status?: "DRAFT" | "PENDING" | "IN_PROGRESS" | "COMPLETED" | "CANCELLED" | "RETURNED" | "REFUNDED";
      /**
       * @description * `SALE` - Sale
       * * `ORDER` - Order
       * * `AGREEMENT` - Convenio de Pago
       * @enum {string}
       */
      order_type: "SALE" | "ORDER" | "AGREEMENT";
      /**
       * @description * `PENDING` - Pending
       * * `PARTIAL` - Partial
       * * `INVOICED` - Invoiced
       * * `PAID` - Paid
       * * `REFUNDED` - Refunded
       * @enum {string}
       */
      payment_status?: "PENDING" | "PARTIAL" | "INVOICED" | "PAID" | "REFUNDED";
      /**
       * Estado de entrega
       * @description Indica si la orden ya fue entregada al cliente
       *
       * * `PENDING` - Pendiente
       * * `IN_PROGRESS` - En progreso
       * * `DELIVERED` - Entregado
       * * `PARTIAL` - Parcial
       * @enum {string}
       */
      delivery_status?: "PENDING" | "IN_PROGRESS" | "DELIVERED" | "PARTIAL";
      /**
       * Fecha de entrega
       * Format: date-time
       */
      delivered_at?: string | null;
      /**
       * Order date and time
       * Format: date-time
       */
      date: string;
      /**
       * Format: double
       * @description Use decimals for monetary precision
       */
      total_amount?: number;
      /**
       * Format: double
       * @description Use decimals for monetary precision
       */
      total_cost?: number;
      /**
       * Tasa de IVA (%)
       * Format: double
       * @description Tasa de IVA aplicada a esta orden (desde BranchFinanceConfig)
       */
      tax_rate?: number;
      /**
       * Monto Neto (sin IVA)
       * Format: double
       * @description Monto neto = total_amount / (1 + tax_rate/100)
       */
      net_amount?: number;
      /**
       * Monto IVA
       * Format: double
       * @description Monto de IVA = total_amount - net_amount
       */
      tax_amount?: number;
      payment_fees?: number;
      /** Payment Days */
      day_pay_fees?: number;
      /** Observations */
      observation?: string | null;
      driver_note?: string | null;
      address?: string | null;
      delivery_address?: string | null;
      /** Format: date-time */
      delivery_date?: string | null;
      /**
       * Format: double
       * @description Latitude of the order location
       */
      latitude?: number | null;
      /**
       * Format: double
       * @description Longitude of the order location
       */
      longitude?: number | null;
      /**
       * Razón de Cancelación
       * @description Razón por la cual se canceló la orden
       */
      cancellation_reason?: string | null;
      items?: {
          [key: string]: unknown;
        }[];
    };
